import java.util.*;
class Solution {
    static boolean solve(String s) {
        StringBuilder sb = new StringBuilder(); for (char c : s.toCharArray()) if (Character.isLetterOrDigit(c)) sb.append(Character.toLowerCase(c)); String cleaned = sb.toString(); int lo = 0, hi = cleaned.length() - 1;
        while (lo < hi) {
            if (cleaned.charAt(lo) != cleaned.charAt(hi)) return false;
            lo++; hi--;
        }
        return true;
    }
}
